    public static Bootstrap.Result read(JsonElement value){var object=value.getAsJsonObject();var supplied=object.getAsJsonObject("options");PlsModelInput.index(supplied.get("samples"));supplied.get("seed").getAsBigDecimal().longValueExact();Bootstrap.Options options=new Gson().fromJson(supplied,Bootstrap.Options.class);int successful=PlsModelInput.index(object.get("successful")),failed=PlsModelInput.index(object.get("failed"));if(successful<Math.max(30,(int)Math.ceil(.8*options.samples()))||successful>options.samples()||failed<0||successful+failed!=options.samples())throw new IllegalArgumentException("Invalid archived bootstrap accounting.");Map<String,Integer> failures=new LinkedHashMap<>();for(var entry:object.getAsJsonObject("failures").entrySet()){int count=PlsModelInput.index(entry.getValue());if(count<0)throw new IllegalArgumentException("Negative archived bootstrap failure count.");failures.put(entry.getKey(),count);}if(failures.values().stream().mapToLong(Integer::longValue).sum()!=failed)throw new IllegalArgumentException("Archived failure reasons do not total failed attempts.");List<Bootstrap.Estimate> estimates=new ArrayList<>();
        for(var item:object.getAsJsonArray("estimates")){var raw=item.getAsJsonObject();var parameter=raw.getAsJsonObject("parameter");var descriptor=new Bootstrap.Parameter(parameter.get("family").getAsString(),PlsModelInput.index(parameter.get("source")),PlsModelInput.index(parameter.get("target")),PlsModelInput.index(parameter.get("column")),parameter.get("label").getAsString());double original=number(raw,"original"),mean=number(raw,"mean"),error=number(raw,"standardError"),probability=number(raw,"pValue"),lower=number(raw,"lower"),upper=number(raw,"upper");if(!Double.isFinite(original)||!Double.isFinite(mean)||!Double.isFinite(error)||error<0||Double.isInfinite(probability)||Double.isFinite(probability)&&(probability<0||probability>1)||Double.isFinite(lower)&&Double.isFinite(upper)&&lower>upper)throw new IllegalArgumentException("Invalid archived bootstrap estimate.");estimates.add(new Bootstrap.Estimate(descriptor,original,mean,error,number(raw,"statistic"),probability,lower,upper,interval(raw.getAsJsonObject("interval")),interval(raw.getAsJsonObject("correctedInterval"))));}
        return new Bootstrap.Result(options,object.get("method").getAsString(),object.get("randomGenerator").getAsString(),object.get("signHandling").getAsString(),successful,failed,failures,estimates,Arrays.asList(new Gson().fromJson(object.get("warnings"),String[].class)),object.has("estimator")&&!object.get("estimator").isJsonNull()?object.get("estimator").getAsString():"unspecified archived estimator");}
